// This script is generated by Gemini
using UnityEngine;
using System.Collections;

public class CarAnimation : MonoBehaviour
{
    [Header("Animation Settings")]
    [Tooltip("Drag the background car object with the Mesh Renderer here")]
    public MeshRenderer carMesh;
    
    [Tooltip("Drag your 8 car PNGs here in order")]
    public Texture2D[] animationFrames;
    
    public float framesPerSecond = 12f;

    void Start()
    {
        if (carMesh != null && animationFrames.Length > 0)
        {
            StartCoroutine(PlayLoopingAnimation());
        }
    }

    private IEnumerator PlayLoopingAnimation()
    {
        float delay = 1f / framesPerSecond;
        int currentIndex = 0;

        // This loop runs infinitely while the car exists in the scene
        while (true)
        {
            carMesh.material.mainTexture = animationFrames[currentIndex];
            
            // Move to the next frame, and wrap back to 0 when it reaches the end
            currentIndex = (currentIndex + 1) % animationFrames.Length;
            
            yield return new WaitForSeconds(delay);
        }
    }
}